val even: DeepRecursiveFunction<Long, Boolean> = DeepRecursiveFunction { n ->
    if (n == 0L) true else callRecursive(odd, n - 1)
}
val odd: DeepRecursiveFunction<Long, Boolean> = DeepRecursiveFunction { n ->
    if (n == 0L) false else callRecursive(even, n - 1)
}

fun main() = println(even(1_000_000))   // no StackOverflowError
